class Solution {
public:
    vector<int> movesToStamp(string stamp, string target) {
        int s_len = stamp.size(), t_len = target.size();
        vector<int> res;
        int total_stamped = 0;
        bool changed = true;

        auto can_stamp = [&](int idx) -> int {
            int new_wildcards = 0;
            for (int i = 0; i < s_len; ++i) {
                if (target[idx + i] == '?') continue;
                if (target[idx + i] != stamp[i]) return 0;
                new_wildcards++;
            }
            return new_wildcards;
        };

        while (total_stamped < t_len && changed) {
            changed = false;
            for (int i = 0; i <= t_len - s_len; ++i) {
                int cnt = can_stamp(i);
                if (cnt > 0) {
                    res.push_back(i);
                    total_stamped += cnt;
                    changed = true;
                    for (int j = 0; j < s_len; ++j) target[i + j] = '?';
                    if (total_stamped == t_len) break;
                }
            }
        }

        if (total_stamped != t_len) return {};
        reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public int[] movesToStamp(String stamp, String target) {
        int sLen = stamp.length(), tLen = target.length();
        char[] sArr = stamp.toCharArray();
        char[] tArr = target.toCharArray();
        List<Integer> res = new ArrayList<>();
        int totalStamped = 0;
        boolean changed = true;

        while (totalStamped < tLen && changed) {
            changed = false;
            for (int i = 0; i <= tLen - sLen; i++) {
                int newWildcards = 0;
                boolean valid = true;
                for (int j = 0; j < sLen; j++) {
                    if (tArr[i + j] == '?') continue;
                    if (tArr[i + j] != sArr[j]) {
                        valid = false;
                        break;
                    }
                    newWildcards++;
                }
                if (valid && newWildcards > 0) {
                    res.add(i);
                    totalStamped += newWildcards;
                    changed = true;
                    for (int j = 0; j < sLen; j++) tArr[i + j] = '?';
                    if (totalStamped == tLen) break;
                }
            }
        }

        if (totalStamped != tLen) return new int[0];
        int[] ans = new int[res.size()];
        for (int i = 0; i < res.size(); i++) {
            ans[i] = res.get(res.size() - 1 - i);
        }
        return ans;
    }
}

var movesToStamp = function(stamp, target) {
    const sLen = stamp.length, tLen = target.length;
    const tArr = target.split('');
    const res = [];
    let totalStamped = 0;
    let changed = true;

    const canStamp = (idx) => {
        let newWildcards = 0;
        for (let i = 0; i < sLen; i++) {
            if (tArr[idx + i] === '?') continue;
            if (tArr[idx + i] !== stamp[i]) return 0;
            newWildcards++;
        }
        return newWildcards;
    };

    while (totalStamped < tLen && changed) {
        changed = false;
        for (let i = 0; i <= tLen - sLen; i++) {
            const cnt = canStamp(i);
            if (cnt > 0) {
                res.push(i);
                totalStamped += cnt;
                changed = true;
                for (let j = 0; j < sLen; j++) tArr[i + j] = '?';
                if (totalStamped === tLen) break;
            }
        }
    }

    if (totalStamped !== tLen) return [];
    return res.reverse();
};
